// Reconcile Gmail-claimed financial events against bank-confirmed ones.
//
// Inputs:
//   /data/finance-events/gmail/*.json — claims ("Chase says you spent $X")
//   /data/finance-events/bank/<institution>/*.json — confirmations
//
// Output:
//   For each Gmail event, look for a bank event with matching amount (within
//   $0.50) and date (within 3 days). Tag the gmail record with reconciliation
//   status: 'verified', 'unconfirmed', 'mismatched'. Write the verdict to
//   /data/finance-events/reconciled/. Surface unconfirmed/mismatched to chat.
//
// Bank events with no matching Gmail claim are tagged 'unexplained' and also
// flagged (silent money movements are exactly the thing the family wants to
// know about).
//
// State file remembers what we've already reconciled so we don't re-alert
// on every hourly tick.

const fs = require('fs');
const path = require('path');

const GMAIL_DIR = '/data/finance-events/gmail';
const BANK_ROOT = '/data/finance-events/bank';
const OUT_DIR = '/data/finance-events/reconciled';
const STATE_FILE = '/data/finance-events/_reconcile_state.json';
fs.mkdirSync(OUT_DIR, { recursive: true });

let state = { reconciled_ids: {} };
try { state = JSON.parse(fs.readFileSync(STATE_FILE, 'utf8')); } catch (_) {}

function loadDir(dir) {
  const items = [];
  let entries;
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch (_) { return items; }
  for (const e of entries) {
    if (e.name.startsWith('_')) continue;
    const full = path.join(dir, e.name);
    if (e.isDirectory()) {
      items.push(...loadDir(full));
    } else if (e.name.endsWith('.json')) {
      try { items.push({ file: full, rec: JSON.parse(fs.readFileSync(full, 'utf8')) }); } catch (_) {}
    }
  }
  return items;
}

const gmail = loadDir(GMAIL_DIR);
const bank = loadDir(BANK_ROOT);

function dayDiff(a, b) {
  if (!a || !b) return Infinity;
  const da = new Date(a).getTime();
  const db = new Date(b).getTime();
  if (Number.isNaN(da) || Number.isNaN(db)) return Infinity;
  return Math.abs(da - db) / 86_400_000;
}

const AMOUNT_TOL = 0.50;
const DATE_TOL_DAYS = 3;

const alerts = [];
const usedBankIds = new Set();

for (const g of gmail) {
  const gid = g.rec.gmail_id;
  if (state.reconciled_ids[gid]) continue;
  const gAmount = g.rec.extracted && g.rec.extracted.amount;
  const gDate = g.rec.internal_date;
  if (gAmount == null) {
    state.reconciled_ids[gid] = { status: 'no-amount', at: new Date().toISOString() };
    continue;
  }
  let best = null;
  let bestScore = Infinity;
  for (const b of bank) {
    const t = b.rec.transaction || {};
    const bAmount = t.amount;
    const bDate = t.posted;
    if (bAmount == null) continue;
    const amtDiff = Math.abs(Math.abs(bAmount) - Math.abs(gAmount));
    const dDiff = dayDiff(gDate, bDate);
    if (amtDiff > AMOUNT_TOL) continue;
    if (dDiff > DATE_TOL_DAYS) continue;
    const score = amtDiff + dDiff;
    if (score < bestScore && !usedBankIds.has(b.file)) {
      bestScore = score;
      best = b;
    }
  }
  let status = 'unconfirmed';
  let bankRef = null;
  if (best) {
    status = 'verified';
    usedBankIds.add(best.file);
    bankRef = path.basename(best.file);
  }
  state.reconciled_ids[gid] = { status, at: new Date().toISOString(), bankRef };
  if (status !== 'verified') {
    alerts.push({
      kind: 'unconfirmed-gmail-claim',
      subject: g.rec.subject,
      from: g.rec.from,
      amount: gAmount,
      direction: g.rec.extracted && g.rec.extracted.direction,
      date: gDate
    });
  }
}

for (const b of bank) {
  if (usedBankIds.has(b.file)) continue;
  const t = b.rec.transaction || {};
  const bid = b.rec.institution + ':' + (t.fitid || (t.posted + '-' + t.amount + '-' + (t.name || '')));
  if (state.reconciled_ids[bid]) continue;
  // Don't alert on small auto-pay round-trip noise; threshold ~$5.
  if (t.amount == null || Math.abs(t.amount) < 5) {
    state.reconciled_ids[bid] = { status: 'noise-skip', at: new Date().toISOString() };
    continue;
  }
  state.reconciled_ids[bid] = { status: 'unexplained', at: new Date().toISOString() };
  alerts.push({
    kind: 'unexplained-bank-tx',
    institution: b.rec.institution,
    amount: t.amount,
    posted: t.posted,
    name: t.name
  });
}

fs.writeFileSync(STATE_FILE, JSON.stringify(state, null, 2));

// Persist the run summary even if no alerts (audit trail).
const runSummary = {
  ran_at: new Date().toISOString(),
  gmail_count: gmail.length,
  bank_count: bank.length,
  alert_count: alerts.length
};
const safeTs = runSummary.ran_at.replace(/[:.]/g, '-');
fs.writeFileSync(path.join(OUT_DIR, `${safeTs}__run.json`), JSON.stringify({ ...runSummary, alerts }, null, 2));

if (alerts.length === 0) {
  return [{ json: { skipped: true, reason: 'no-alerts', ...runSummary } }];
}

// Compose a chat message bundling all alerts from this run.
const lines = ['*Reconcile · ' + new Date(runSummary.ran_at).toLocaleString() + '*'];
for (const a of alerts.slice(0, 20)) {
  if (a.kind === 'unconfirmed-gmail-claim') {
    lines.push(`⚠️ Gmail claim with no bank match: $${a.amount} (${a.direction || 'unknown dir'}) — ${a.subject}`);
  } else {
    lines.push(`❓ Unexplained bank tx: ${a.institution} $${a.amount} on ${a.posted} — ${a.name || 'no description'}`);
  }
}
if (alerts.length > 20) lines.push(`…and ${alerts.length - 20} more.`);

return [{
  json: {
    chat_text: lines.join('\n'),
    ...runSummary
  }
}];
